/**
 * Builds src/features/charts/web/chartHtml.generated.ts — the self-contained page the chart
 * WebView loads: TradingView's Lightweight Charts (Apache-2.0, pinned in devDependencies) plus
 * our bridge (src/features/charts/web/bridge.js), inlined into one HTML string.
 *
 *     npm run build:chart
 *
 * Inlined rather than fetched: the chart opens with no network round trip, works offline, and
 * ships exactly the library version the app was tested with. Re-run after editing bridge.js or
 * upgrading lightweight-charts; the generated file is committed, so builds need neither step.
 */
import { createHash } from 'node:crypto';
import { readFileSync, writeFileSync } from 'node:fs';
import { dirname, join } from 'node:path';
import { fileURLToPath } from 'node:url';

const root = join(dirname(fileURLToPath(import.meta.url)), '..');
// Read from the package directory: its `exports` map does not expose the standalone build.
const libDir = join(root, 'node_modules/lightweight-charts');
const libVersion = JSON.parse(readFileSync(join(libDir, 'package.json'), 'utf8')).version;
const lib = readFileSync(join(libDir, 'dist/lightweight-charts.standalone.production.js'), 'utf8');
const bridge = readFileSync(join(root, 'src/features/charts/web/bridge.js'), 'utf8');

for (const [name, source] of [
  ['lightweight-charts', lib],
  ['bridge.js', bridge],
]) {
  if (/<\/script/i.test(source))
    throw new Error(`${name} contains "</script" and cannot be inlined`);
}

const html = `<!doctype html>
<html>
<head>
<meta charset="utf-8">
<meta name="viewport" content="width=device-width,initial-scale=1,maximum-scale=1,user-scalable=no">
<style>
html,body{margin:0;padding:0;height:100%;overflow:hidden;-webkit-user-select:none;user-select:none;-webkit-touch-callout:none;-webkit-tap-highlight-color:transparent}
#chart{position:absolute;top:0;right:0;bottom:0;left:0}
</style>
</head>
<body>
<div id="chart"></div>
<script>${lib}</script>
<script>${bridge}</script>
</body>
</html>`;

const hash = createHash('sha256').update(html).digest('hex').slice(0, 16);
const out = `/* eslint-disable */
// GENERATED by scripts/build-chart-html.mjs — do not edit; run \`npm run build:chart\`.
// Lightweight Charts ${libVersion} © TradingView, Inc. — Apache License 2.0
// (https://github.com/tradingview/lightweight-charts). Attribution is shown on the chart.

export const CHART_LIBRARY_VERSION = '${libVersion}';
export const CHART_HTML_HASH = '${hash}';
export const CHART_HTML = ${JSON.stringify(html)};
`;

writeFileSync(join(root, 'src/features/charts/web/chartHtml.generated.ts'), out);
console.log(
  `chartHtml.generated.ts: lightweight-charts ${libVersion}, ${(html.length / 1024).toFixed(0)} KB, ${hash}`,
);
